package com.oms.channel.platform;
import com.oms.common.api.OrderGoodsClient;
import com.ruoyi.common.core.domain.R;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.channel.platform.ChannelPlatformService.map;
class StockSyncTest {
 ChannelPlatformTest f;StockSyncService service;StockSyncInventory inventory;StockSyncOrders orders;OrderGoodsClient goods;StockSyncPlatform remote;long group;
 @BeforeEach void setup(){f=new ChannelPlatformTest();f.setup();for(String table:Arrays.asList("channel_stock_sync_run","channel_stock_sync_link","channel_stock_sync_group","channel_stock_sync_sim","channel_product_binding_event","channel_platform_product","channel_product_pull_item","channel_product_pull","channel_product_sim"))f.db.update("DELETE FROM "+table);f.simulation(true);f.service.simulate("QM",101,"tester");f.db.update("UPDATE t_channel SET sync_enabled=1,company_code='qm' WHERE channel_id=101");
  remote=new StockSyncPlatform();remote.platform=f.service;remote.db=f.db;inventory=mock(StockSyncInventory.class);orders=mock(StockSyncOrders.class);goods=mock(OrderGoodsClient.class);
  when(inventory.snapshot(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("available",100,"components",Collections.emptyList())));when(orders.guard(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("can_increase",true,"allow_public_stock",true,"reason","")));when(goods.goods(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.singletonList(map("sku_sn","A","goods_name","测试商品","is_package",0,"is_fd",0))));
  service=new StockSyncService();service.db=f.db;service.transactionManager=new DataSourceTransactionManager(f.db.getDataSource());service.inventory=inventory;service.orders=orders;service.goods=goods;service.remote=remote;service.platform=f.service;service.logs=new PlatformInteractionLog();service.logs.db=f.db;service.logs.transactionManager=service.transactionManager;
  service.products=new PlatformProductService();service.products.db=f.db;service.products.platform=f.service;service.products.goods=goods;service.products.transactionManager=service.transactionManager;service.products.logs=service.logs;
  String shop=f.db.queryForObject("SELECT expected_shop_id FROM channel_platform_binding WHERE channel_id=101",String.class);
  for(int i=1;i<=3;i++)f.db.update("INSERT INTO channel_platform_product(company_code,channel_id,platform_shop_id,item_id,sku_id,title,binding_state,oms_sku_sn,listing_state,platform_quantity,identity_hash) VALUES ('QM',101,?,?,?,'测试链接','BOUND','A','onsale',0,'TEST')",shop,"90000000000000000"+i,"91000000000000000"+i);
  for(int i=1;i<=3;i++)f.db.update("INSERT INTO channel_stock_sync_sim(company_code,channel_id,item_id,sku_id,quantity) VALUES ('QM',101,?, ?,0)","90000000000000000"+i,"91000000000000000"+i);
 }
 @AfterEach void cleanup(){if(f!=null)f.closePool();}
 Map<String,Object> link(int i,int weight){return map("binding_id",f.db.queryForObject("SELECT id FROM channel_platform_product WHERE item_id=?",Long.class,"90000000000000000"+i),"binding_revision",1,"name","链接"+i,"item_id","90000000000000000"+i,"sku_id","91000000000000000"+i,"weight",weight,"enabled",1,"quantity_cap",null);}
 Map<String,Object> body(){return map("channel_id",101,"sku_sn","A","safety_stock",10,"quantity_cap",null,"enabled",0,"links",Arrays.asList(link(1,60),link(2,30),link(3,10)));}
 long create(){Map<String,Object> saved=service.save("QM",body(),"tester");group=((Number)saved.get("id")).longValue();return group;}
 long qty(int i){return f.db.queryForObject("SELECT quantity FROM channel_stock_sync_sim WHERE item_id=?",Long.class,"90000000000000000"+i);}
 String state(){return service.detail("QM",group).get("state").toString();}
 void current(int i,long n){f.db.update("UPDATE channel_stock_sync_sim SET quantity=? WHERE item_id=?",n,"90000000000000000"+i);}
 @Test void proportionIntegerCapAndSafetyAreConserved(){List<Map<String,Object>> r=StockSyncAllocation.distribute(100,10,null,Arrays.asList(link(1,60),link(2,30),link(3,10)));assertEquals(Arrays.asList(54L,27L,9L),Arrays.asList(r.get(0).get("target"),r.get(1).get("target"),r.get(2).get("target")));}
 @Test void roundingNeverExceedsBudgetAndTiesAreStable(){Map<String,Object>a=link(1,1),b=link(2,1),c=link(3,1);a.put("id",1);b.put("id",2);c.put("id",3);List<Map<String,Object>> result=StockSyncAllocation.distribute(2,0,null,Arrays.asList(a,b,c));assertEquals(2,result.stream().mapToLong(x->((Number)x.get("target")).longValue()).sum());assertEquals(1L,result.get(0).get("target"));assertEquals(0L,result.get(2).get("target"));}
 @Test void linkCapDoesNotSilentlyReassignItsShare(){Map<String,Object>a=link(1,60);a.put("quantity_cap",10);List<Map<String,Object>> r=StockSyncAllocation.distribute(100,0,50L,Arrays.asList(a,link(2,40)));assertEquals(10L,r.get(0).get("target"));assertEquals(20L,r.get(1).get("target"));}
 @Test void previewDoesNotWritePlatformOrLocalPhysicalStock(){create();assertEquals(90L,((List<Map<String,Object>>)service.preview("QM",group).get("links")).stream().mapToLong(x->((Number)x.get("target")).longValue()).sum());assertEquals(0,qty(1));assertEquals(0,f.client.requests.size());assertEquals(0,f.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE action='tmall.item.quantity.update'",Integer.class));}
 @Test void realServiceSimulationSyncsThreeLinksAndKeepsLongIds(){create();service.execute("QM",group,"tester");assertEquals("SUCCESS",state());assertEquals(54,qty(1));assertEquals(27,qty(2));assertEquals(9,qty(3));assertTrue(f.client.requests.isEmpty());assertEquals(3,f.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE category='STOCK' AND action='tmall.item.quantity.update' AND entry_kind='SIMULATION' AND result='SUCCESS'",Integer.class));}
 @Test void unchangedReplayDoesNotWriteAgain(){create();service.execute("QM",group,"tester");int before=f.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE action='tmall.item.quantity.update'",Integer.class);service.execute("QM",group,"tester");assertEquals(before,f.db.queryForObject("SELECT COUNT(*) FROM channel_interaction_log WHERE action='tmall.item.quantity.update'",Integer.class));}
 @Test void decreaseFailureBlocksAllIncreases(){create();current(1,60);f.db.update("UPDATE channel_stock_sync_sim SET fail_write='FAILED' WHERE item_id='900000000000000001'");service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(0,qty(2));assertEquals(0,qty(3));assertEquals(60,qty(1));}
 @Test void unknownWriteIsQueriedBeforeAnyRetry(){create();current(1,60);f.db.update("UPDATE channel_stock_sync_sim SET fail_write='UNKNOWN' WHERE item_id='900000000000000001'");service.execute("QM",group,"tester");assertEquals("UNKNOWN",state());assertEquals(54,qty(1));assertEquals(0,qty(2));f.db.update("UPDATE channel_stock_sync_sim SET fail_write=''");service.execute("QM",group,"tester");assertEquals("SUCCESS",state());assertEquals(27,qty(2));}
 @Test void divergentUnknownResultCannotBeBlindlyReplayed(){create();service.execute("QM",group,"tester");f.db.update("UPDATE channel_stock_sync_link SET state='UNKNOWN',pending_quantity=50 WHERE group_id=? AND item_id='900000000000000001'",group);current(1,40);service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(40,qty(1));}
 @Test void pausedLinkRetainsItsPlatformExposure(){create();Map<String,Object>b=service.detail("QM",group);List<Map<String,Object>>l=(List<Map<String,Object>>)b.get("links");l.get(2).put("enabled",0);service.save("QM",b,"tester");current(3,10);service.execute("QM",group,"tester");assertEquals(10,qty(3));assertTrue(qty(1)+qty(2)+qty(3)<=90);}
 @Test void staleOrderIntakeAllowsDecreasesButNoIncreases(){create();current(1,60);when(orders.guard(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("can_increase",false,"allow_public_stock",true,"reason","拉单滞后")));service.execute("QM",group,"tester");assertEquals("BLOCKED",state());assertEquals(54,qty(1));assertEquals(0,qty(2));}
 @Test void unpaidPlatformTradeBlocksReplenishment(){create();String pending="[{\"tid\":\"777\",\"status\":\"WAIT_BUYER_PAY\",\"modified\":\"2026-10-19 00:00:00\",\"orders\":{\"order\":[{\"num_iid\":\"900000000000000001\",\"sku_id\":\"910000000000000001\"}]}}]";f.db.update("UPDATE channel_stock_sync_sim SET pending_trades=? WHERE item_id='900000000000000001'",pending);when(orders.guard(anyString(),argThat(m->m.containsKey("trades")&&((List<?>)m.get("trades")).size()>0),anyString())).thenReturn(R.ok(map("can_increase",false,"allow_public_stock",true,"reason","存在未付款订单")));service.execute("QM",group,"tester");assertEquals("BLOCKED",state());assertEquals(0,qty(1));}
 @Test void unsupportedInventoryModeNeverWritesZero(){create();current(1,20);f.db.update("UPDATE channel_stock_sync_sim SET inventory_mode=2");service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(20,qty(1));}
 @Test void missingInventoryAndUnsupportedBagsNeverClearPlatformStock(){create();current(1,20);when(goods.goods(anyString(),anyList(),anyString())).thenReturn(R.ok(Collections.singletonList(map("is_fd",1))));service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(20,qty(1));}
 @Test void zeroAvailableIsARealZeroNotFailure(){create();current(1,20);when(inventory.snapshot(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("available",0)));service.execute("QM",group,"tester");assertEquals("SUCCESS",state());assertEquals(0,qty(1));}
 @Test void targetCannotBeOwnedByAnotherGroup(){create();Map<String,Object>b=body();b.put("sku_sn","B");assertThrows(IllegalArgumentException.class,()->service.save("QM",b,"tester"));assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM channel_stock_sync_group",Integer.class));}
 @Test void tenantAndStaleRevisionAreRejected(){create();assertThrows(IllegalArgumentException.class,()->service.detail("OTHER",group));Map<String,Object>b=service.detail("QM",group);b.put("revision",99);assertThrows(IllegalArgumentException.class,()->service.save("QM",b,"tester"));}
 @Test void leasePreventsConfigChangeAndDuplicateExecution(){create();String lease=service.claim("QM",group);assertThrows(IllegalArgumentException.class,()->service.execute("QM",group,"tester"));assertThrows(IllegalArgumentException.class,()->service.save("QM",service.detail("QM",group),"tester"));service.fence("QM",group,lease,1);}
 @Test void zeroAndDisableReleasesExposureOnlyAfterSuccess(){create();current(1,20);long link=((Number)((List<Map<String,Object>>)service.detail("QM",group).get("links")).get(0).get("id")).longValue();service.linkAction("QM",group,link,map("revision",1,"action","ZERO_DISABLE","confirmed",true,"reason","验收退出"),"tester");assertEquals(0,qty(1));assertEquals(0,f.db.queryForObject("SELECT enabled FROM channel_stock_sync_link WHERE id=?",Integer.class,link));}
 @Test void closedShopSwitchBlocksAllWrites(){create();current(1,20);f.db.update("UPDATE t_channel SET sync_enabled=0 WHERE channel_id=101");service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(20,qty(1));}
 @Test void incorrectUnobservedMappingCanBeRemovedWithoutTouchingPlatform(){create();Map<String,Object> b=service.detail("QM",group);((List<?>)b.get("links")).remove(2);service.save("QM",b,"tester");assertEquals(2,((List<?>)service.detail("QM",group).get("links")).size());assertEquals(0,qty(3));}
 @Test void observedMappingCannotBeDeletedSilently(){create();service.execute("QM",group,"tester");Map<String,Object> b=service.detail("QM",group);((List<?>)b.get("links")).remove(2);assertThrows(IllegalArgumentException.class,()->service.save("QM",b,"tester"));}
 @Test void failedZeroExitKeepsLinkAndReleasesGroupForRetry(){create();current(1,20);f.db.update("UPDATE channel_stock_sync_sim SET fail_write='FAILED' WHERE item_id='900000000000000001'");long id=((Number)((List<Map<String,Object>>)service.detail("QM",group).get("links")).get(0).get("id")).longValue();assertThrows(TmallClient.Failure.class,()->service.linkAction("QM",group,id,map("revision",1,"action","ZERO_DISABLE","confirmed",true,"reason","验收失败重试"),"tester"));assertEquals("FAILED",state());assertEquals(20,qty(1));assertEquals(1,f.db.queryForObject("SELECT enabled FROM channel_stock_sync_link WHERE id=?",Integer.class,id));service.enqueue("QM",group,1,"tester");assertEquals("PENDING",state());}
 @Test void staleBindingStopsEveryStockWrite(){create();current(1,20);f.db.update("UPDATE channel_platform_product SET binding_revision=binding_revision+1 WHERE channel_id=101");service.execute("QM",group,"tester");assertEquals("FAILED",state());assertEquals(20,qty(1));assertEquals(0,qty(2));}
 @Test void zeroExitReleasesBindingEvenAfterSpecChanged(){create();current(1,20);f.db.update("UPDATE channel_platform_product SET binding_state='REVIEW',binding_revision=2");Map<String,Object> l=((List<Map<String,Object>>)service.detail("QM",group).get("links")).get(0);service.linkAction("QM",group,((Number)l.get("id")).longValue(),map("revision",1,"action","ZERO_DISABLE","confirmed",true,"reason","变更后退出"),"tester");assertNotNull(service.links("QM",group).get(0).get("retired_at"));assertEquals(0,qty(1));}
 @Test void platformObservationIsRefreshedAfterConfirmedWrite(){create();service.execute("QM",group,"tester");assertEquals(54L,f.db.queryForObject("SELECT observed_quantity FROM channel_stock_sync_link WHERE group_id=? AND item_id='900000000000000001'",Long.class,group));}
}
